Node* closest_node = nullptr;
float min_dist = std::numeric_limits<float>::max();

for (std::size_t i = 0; i < m_nodes.size(); ++i) {
    // consider only nodes that belong to non‑footway roads
    if (node_to_road.find(static_cast<int>(i)) == node_to_road.end())
        continue;

    const auto& node = m_nodes[i];
    float dx = node.x - x;
    float dy = node.y - y;
    float dist = std::sqrt(dx * dx + dy * dy);

    if (dist < min_dist) {
        min_dist = dist;
        closest_node = &m_nodes[i];
    }
}

// Fallback in the unlikely event no node was found
if (!closest_node) {
    return m_nodes[0];
}
return *closest_node;

